package com.logatron.processor.enrich;
import com.logatron.contracts.ingestion.*;import com.logatron.processor.configuration.IngestionProperties;import com.logatron.processor.deduplicate.Fingerprinter;import com.logatron.processor.parse.*;import com.logatron.processor.protect.SensitiveDataMasker;import org.springframework.stereotype.Component;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;
@Component public class CanonicalEventFactory {private final SeverityNormalizer severity;private final SensitiveDataMasker masker;private final Fingerprinter fingerprints;private final IngestionProperties props;public CanonicalEventFactory(SeverityNormalizer severity,SensitiveDataMasker masker,Fingerprinter fingerprints,IngestionProperties props){this.severity=severity;this.masker=masker;this.fingerprints=fingerprints;this.props=props;}public CanonicalLogEvent create(RawLogEnvelope raw,ParsedLog parsed,SourceMetadata m){Map<String,String>a=new LinkedHashMap<>(masker.mask(parsed.attributes()));Instant timestamp=parsed.timestamp();if(timestamp==null){timestamp=raw.observedTimestamp();a.put("timestampQuality","OBSERVED_FALLBACK");}String stack=masker.mask(parsed.stackTrace());if(stack!=null&&stack.getBytes(StandardCharsets.UTF_8).length>props.ingestion().maxStackTraceBytes()){a.put("stackTraceTruncated","true");a.put("originalStackTraceBytes",Integer.toString(stack.getBytes(StandardCharsets.UTF_8).length));stack=truncate(stack,props.ingestion().maxStackTraceBytes());}String level=severity.normalize(parsed.level());CanonicalLogEvent e=new CanonicalLogEvent(1,raw.eventId(),timestamp,raw.observedTimestamp(),Instant.now(),m.company(),m.companyId(),m.project(),m.projectId(),m.environment(),m.environmentId(),m.server(),m.serverId(),m.hostname(),m.serverIp(),m.service(),m.serviceId(),m.serviceInstance(),m.serviceInstanceId(),m.logFile(),m.logType(),level,severity.number(level),parsed.traceId(),parsed.spanId(),parsed.traceFlags(),parsed.requestId(),parsed.correlationId(),parsed.transactionId(),parsed.orderToken(),parsed.auctionId(),parsed.logger(),parsed.thread(),masker.mask(parsed.message()),masker.mask(parsed.exceptionType()),stack,a,Map.of("source.id",m.logSourceId().toString()),m.classification(),true,null,raw.collector().collectorId(),raw.collector().sourceOffset());return withFingerprint(e,fingerprints.fingerprint(e));}private CanonicalLogEvent withFingerprint(CanonicalLogEvent e,String f){return new CanonicalLogEvent(e.schemaVersion(),e.eventId(),e.timestamp(),e.observedTimestamp(),e.ingestedAt(),e.company(),e.companyId(),e.project(),e.projectId(),e.environment(),e.environmentId(),e.server(),e.serverId(),e.hostname(),e.serverIp(),e.service(),e.serviceId(),e.serviceInstance(),e.serviceInstanceId(),e.logFile(),e.logType(),e.level(),e.severityNumber(),e.traceId(),e.spanId(),e.traceFlags(),e.requestId(),e.correlationId(),e.transactionId(),e.orderToken(),e.auctionId(),e.logger(),e.thread(),e.message(),e.exceptionType(),e.stackTrace(),e.attributes(),e.resourceAttributes(),e.dataClassification(),e.maskingApplied(),f,e.collectorId(),e.sourceOffset());}private String truncate(String s,int max){int end=Math.min(s.length(),max);while(end>0&&s.substring(0,end).getBytes(StandardCharsets.UTF_8).length>max)end--;return s.substring(0,end);}}